// Valida Authorization: Bearer <SYNC_SECRET>. Sale con { url } o throw.
const auth = $input.first().json.headers?.authorization || '';
const secret = $env.SYNC_SECRET || '';
if (!secret) throw new Error('SYNC_SECRET not configured');
if (!auth.startsWith('Bearer ') || auth.slice(7) !== secret) {
  throw new Error('Unauthorized');
}
const url = (($input.first().json.body || {}).url || '').toString().trim();
if (!url) throw new Error('Missing url');
return [{ json: { url } }];

const url = $input.item.json.url || '';
const match = url.match(/models\/(\d+)/);
if (!match) throw new Error('URL de MakerWorld no válida. No se encontró el ID del modelo.');
return { json: { externalId: match[1] } };

const data = $input.item.json;
const instances = data.instances || [];
if (instances.length === 0) throw new Error('No se encontraron perfiles de impresión (instances).');

// Tomamos el primer perfil de impresión disponible (que suele ser el oficial o el más popular)
const firstInstance = instances[0];
const plates = (((firstInstance.extention) || {}).modelInfo || {}).plates || [];

const grams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
const seconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
const hours = Number((seconds / 3600).toFixed(2));

if (!Number.isFinite(grams) || !Number.isFinite(hours) || (grams === 0 && hours === 0)) {
  throw new Error('El modelo no publica estadísticas de slicer (gramos/horas).');
}

return { json: { grams, hours } };
